int dccp_process_incoming_packet(struct sock *sk, struct sk_buff *skb,
                                 struct dccp_hdr *dh, unsigned int len)
{
    if (!sk || !skb || !dh)
        return 1;

    switch (sk->sk_state) {
    case DCCP_LISTEN:
        if (dh->dccph_type == DCCP_PKT_REQUEST) {
            if (len < sizeof(struct dccp_hdr))
                return 1;

            if (dccp_validate_options(skb, dh, len) != 0)
                return 1;

            dccp_handle_connection_request(sk, skb, dh);
        } else {
            return 1;
        }
        break;

    case DCCP_CLOSED:
        return 1;

    case DCCP_REQUESTING:
        if (dh->dccph_type == DCCP_PKT_RESPONSE) {
            if (len < sizeof(struct dccp_hdr))
                return 1;

            if (dccp_validate_options(skb, dh, len) != 0)
                return 1;

            dccp_handle_response_packet(sk, skb, dh);
        } else if (dh->dccph_type == DCCP_PKT_RESET) {
            dccp_teardown_connection(sk, skb, dh);
            return 0;
        } else {
            return 1;
        }
        break;

    case DCCP_PARTOPEN:
        if (dh->dccph_type == DCCP_PKT_DATA || dh->dccph_type == DCCP_PKT_ACK) {
            dccp_process_data_or_ack(sk, skb, dh, len);
        } else if (dh->dccph_type == DCCP_PKT_RESET) {
            dccp_teardown_connection(sk, skb, dh);
            return 0;
        } else {
            return 1;
        }
        break;

    case DCCP_RESPOND:
        if (dh->dccph_type == DCCP_PKT_CONFIRM) {
            dccp_handle_confirm_packet(sk, skb, dh);
        } else {
            return 1;
        }
        break;

    default:
        return 1;
    }

    return 0;
}

int dccp_process_incoming_packet(struct sock *sk, struct sk_buff *skb,
                                 struct dccp_hdr *dh, unsigned int len)
{
    if (!sk || !skb || !dh || len < sizeof(*dh))
        return 1;

    switch (sk->sk_state) {
    case DCCP_LISTEN:
        if (dh->dccph_type == DCCP_PKT_REQUEST) {
            if (dccp_process_options(sk, dh, len) < 0)
                return 1;
            dccp_state_transition(sk, DCCP_RESPOND);
        } else {
            return 1;
        }
        break;
    case DCCP_CLOSED:
        return 1;
    case DCCP_REQUESTING:
        if (dh->dccph_type == DCCP_PKT_RESPONSE) {
            if (dccp_validate_response(sk, dh, len) < 0)
                return 1;
            dccp_state_transition(sk, DCCP_PARTOPEN);
        } else {
            return 1;
        }
        break;
    case DCCP_PARTOPEN:
        if (dh->dccph_type == DCCP_PKT_ACK) {
            if (dccp_process_ack(sk, dh, len) < 0)
                return 1;
        } else if (dh->dccph_type == DCCP_PKT_SYNC) {
            if (dccp_process_sync(sk, dh, len) < 0)
                return 1;
        } else {
            return 1;
        }
        break;
    case DCCP_RESPOND:
        if (dh->dccph_type == DCCP_PKT_DATA) {
            if (dccp_validate_data(sk, dh, len) < 0)
                return 1;
            dccp_state_transition(sk, DCCP_OPEN);
        } else {
            return 1;
        }
        break;
    default:
        return 1;
    }

    return 0;
}

int dccp_process_packet(struct sock *sk, struct sk_buff *skb, struct dccp_hdr *dh, unsigned int len)
{
    int ret = 0;

    switch (sk->sk_state) {
    case DCCP_LISTEN:
        if (dh->dccph_type == DCCP_PKT_REQUEST) {
            if (!dccp_options_parse(skb)) {
                dccp_send_response(sk, skb);
                sk->sk_state = DCCP_RESPOND;
            } else {
                ret = 1;
            }
        } else {
            ret = 1;
        }
        break;

    case DCCP_CLOSED:
        ret = 1;
        break;

    case DCCP_REQUESTING:
        if (dh->dccph_type == DCCP_PKT_RESPONSE) {
            if (!dccp_options_validate(skb)) {
                dccp_send_ack(sk, skb);
                sk->sk_state = DCCP_PARTOPEN;
            } else {
                ret = 1;
            }
        } else {
            ret = 1;
        }
        break;

    case DCCP_PARTOPEN:
        if (dh->dccph_type == DCCP_PKT_DATA || dh->dccph_type == DCCP_PKT_ACK) {
            dccp_receive_data(sk, skb);
        } else if (dh->dccph_type == DCCP_PKT_RESET) {
            dccp_terminate_connection(sk);
            ret = 1;
        } else {
            ret = 1;
        }
        break;

    case DCCP_RESPOND:
        if (dh->dccph_type == DCCP_PKT_ACK) {
            sk->sk_state = DCCP_OPEN;
        } else {
            ret = 1;
        }
        break;

    default:
        ret = 1;
        break;
    }

    return ret;
}

int dccp_process_incoming_packet(struct sock *sk, struct sk_buff *skb,
                                 struct dccp_hdr *dh, unsigned int len)
{
    switch (sk->sk_state) {
    case DCCP_LISTEN:
        if (dh->dccph_type != DCCP_PKT_REQUEST) {
            return 1;
        }
        if (len < sizeof(struct dccp_hdr)) {
            return 1;
        }
        if (dccp_options_parser(skb, dh) < 0) {
            return 1;
        }
        sk->sk_state = DCCP_RESPOND;
        break;
    case DCCP_RESPOND:
        if (dh->dccph_type != DCCP_PKT_DATA) {
            return 1;
        }
        if (len < dccp_hdr_length(skb)) {
            return 1;
        }
        if (dccp_validate_ack(skb, dh) < 0) {
            return 1;
        }
        if (dccp_options_parser(skb, dh) < 0) {
            return 1;
        }
        sk->sk_state = DCCP_OPEN;
        break;
    case DCCP_OPEN:
        if (dh->dccph_type == DCCP_PKT_RESET) {
            dccp_teardown_connection(sk);
            return 0;
        }
        if (len < dccp_hdr_length(skb)) {
            return 1;
        }
        if (dccp_options_parser(skb, dh) < 0) {
            return 1;
        }
        if (dccp_process_data(skb, dh) < 0) {
            return 1;
        }
        break;
    case DCCP_CLOSED:
        return 1;
    case DCCP_REQUESTING:
        if (dh->dccph_type != DCCP_PKT_RESPONSE) {
            return 1;
        }
        if (len < sizeof(struct dccp_hdr)) {
            return 1;
        }
        if (dccp_options_parser(skb, dh) < 0) {
            return 1;
        }
        if (dccp_validate_ack(skb, dh) < 0) {
            return 1;
        }
        sk->sk_state = DCCP_PARTOPEN;
        break;
    case DCCP_PARTOPEN:
        if (dh->dccph_type == DCCP_PKT_RESET) {
            dccp_teardown_connection(sk);
            return 0;
        }
        if (len < dccp_hdr_length(skb)) {
            return 1;
        }
        if (dccp_options_parser(skb, dh) < 0) {
            return 1;
        }
        if (dccp_validate_ack(skb, dh) < 0) {
            return 1;
        }
        if (dccp_process_data(skb, dh) < 0) {
            return 1;
        }
        break;
    default:
        return 1;
    }

    return 0;
}
